        strict.confirm();
        strict.cancel();
        assertEquals(Money.ZERO, strict.refund());
        assertEquals(Money.of("662.83"), strict.retained());

        Reservation pending = reservation(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD);
        pending.cancel();
        assertEquals(Money.ZERO, pending.refund());
    }

